\title{The Two-Colour Ramsey Number as a Computable Function:\\
Exact Values, Recursive and Probabilistic Bounds}
\author{Aristotle}
\date{2026-06-28}

\begin{document}
\maketitle

\begin{abstract}
We present a unified, machine-checked development of finite two-colour Ramsey
theory built on a single primitive: the \emph{arrow relation} $n \to (s,t)$,
asserting that every red/blue edge-colouring of a complete graph on $n$ vertices
contains a red clique of size $s$ or a blue clique of size $t$. From this we
define the \textbf{Ramsey number} as a genuine function
$R:\mathbb{N}\times\mathbb{N}\to\mathbb{N}$ via
$R(s,t)=\min\{n:n\to(s,t)\}$, and establish its complete order-theoretic API.
On this foundation we prove the classical exact values
$R(3,3)=6$, $R(3,4)=9$, $R(4,4)=18$, the off-diagonal base case $R(2,t+1)=t+1$,
colour symmetry $R(s,t)=R(t,s)$, the Erd\H{o}s--Szekeres binomial bound
$R(s+1,t+1)\le\binom{s+t}{s}$ with its recursion
$R(s,t)\le R(s-1,t)+R(s,t-1)$, and the probabilistic lower bound yielding the
explicit sandwich $2^{m-1}<R(2m,2m)\le 4^{2m-1}$ for $m\ge 4$. Each exact value is
obtained by a different extremal mechanism: pure recursion, recursion plus
handshake parity, and recursion plus an algebraic (Paley-graph) construction.
\end{abstract}

\section{Introduction}
Ramsey theory studies the inevitability of order in large structures: any
sufficiently large system, however unstructured, must contain a large ordered
substructure. Frank Ramsey's 1928 theorem guarantees that for any clique sizes
$s,t$ there is a finite threshold beyond which every red/blue colouring of a
complete graph contains a red $K_s$ or a blue $K_t$; the least such threshold is
the Ramsey number $R(s,t)$. We assemble five layers into one framework: an
encoding of the arrow relation with built-in monotonicity; the definition of $R$
as a function; the Erd\H{o}s--Szekeres recursion and binomial bound; exact small
values with explicit extremal colourings; and the probabilistic lower bound with a
resulting exponential sandwich. The organising principle is that the arrow
relation is a two-parameter monotone family --- monotone as the vertex count
grows, antitone as the clique sizes grow.

\section{The arrow relation and its monotonicity}

A red/blue colouring of the complete graph on a vertex set $V$ is encoded by a
single simple graph $G$ on $V$: edges of $G$ are \emph{red}, edges of the
complement $G^{\cc}$ are \emph{blue}. A red $s$-clique is an $s$-clique of $G$; a
blue $t$-clique is an $s$-clique of $G^{\cc}$.

\begin{definition}[Arrow relation]
For $n,s,t\in\mathbb{N}$, write $\Arrows\, n\, s\, t$ (classically $n\to(s,t)$) for
\[
\forall V,\ \forall G,\ \forall W\subseteq V,\ |W|\ge n \Rightarrow
\bigl(\exists S\subseteq W,\ G.\mathrm{IsNClique}\,s\,S\bigr)\vee
\bigl(\exists S\subseteq W,\ G^{\cc}.\mathrm{IsNClique}\,t\,S\bigr).
\]
Quantifying over an arbitrary vertex type and a finite subset $W$ bakes
monotonicity into the definition and makes the recursion easy to state.
\end{definition}

\begin{lemma}[Vertex monotonicity, \texttt{Arrows.mono}]
If $n\to(s,t)$ and $n\le n'$ then $n'\to(s,t)$.
\end{lemma}
\begin{proof}
Immediate from $|W|\ge n'\ge n$.
\end{proof}

\begin{lemma}[Clique-size monotonicity, \texttt{arrows\_mono\_red/blue}]
If $n\to(s,t)$ and $s'\le s$ then $n\to(s',t)$; symmetrically in $t$.
\end{lemma}
\begin{proof}[Proof sketch]
Cliques are hereditary in size: any $s$-clique contains an $s'$-subclique. The
blue case follows by colour symmetry (Lemma~\ref{lem:symm}).
\end{proof}

\section{The Ramsey number as a function}

\begin{lemma}[\texttt{arrows\_witness}]\label{lem:witness}
For all $s,t$, there exists $n$ with $n\to(s,t)$.
\end{lemma}
\begin{proof}[Proof sketch]
If $s=0$ or $t=0$ the empty set is a $0$-clique, so $0$ works. Otherwise write
$s=S{+}1$, $t=T{+}1$ and use the binomial bound (Theorem~\ref{thm:binom}) with
threshold $\binom{S+T}{S}$.
\end{proof}

\begin{definition}[Ramsey number]
$R(s,t):=\inf\{\,n:n\to(s,t)\,\}$. By Lemma~\ref{lem:witness} the set is
non-empty, so the infimum is attained.
\end{definition}

\begin{theorem}[\texttt{ramseyNumber\_mem}]
$R(s,t)\to(s,t)$: the Ramsey number is itself a working threshold.
\end{theorem}

\begin{theorem}[\texttt{ramseyNumber\_le}]
If $n\to(s,t)$ then $R(s,t)\le n$: it is the least working threshold.
\end{theorem}

\begin{theorem}[\texttt{lt\_ramseyNumber}]
If $\lnot(n\to(s,t))$ then $n<R(s,t)$.
\end{theorem}

\begin{theorem}[Sandwich, \texttt{ramseyNumber\_eq}]\label{thm:sandwich}
If $n\to(s,t)$ but $\lnot((n-1)\to(s,t))$, then $R(s,t)=n$.
\end{theorem}
\begin{proof}[Proof sketch]
$R(s,t)\le n$ by leastness; if $R(s,t)<n$ then $R(s,t)\le n-1$ and vertex
monotonicity would give $(n-1)\to(s,t)$, a contradiction. For $n=0$ the
hypotheses are contradictory and the claim holds vacuously.
\end{proof}

\section{The Erd\H{o}s--Szekeres recursion and binomial bound}

\begin{lemma}[Step, \texttt{arrows\_step}]\label{lem:step}
If $m,n>0$, $m\to(s,t{+}1)$ and $n\to(s{+}1,t)$, then $(m+n)\to(s{+}1,t{+}1)$.
\end{lemma}
\begin{proof}[Proof sketch]
Fix a vertex $v$ in a colouring of $W$ with $|W|\ge m+n$. The non-$v$ vertices
split into red neighbours $R$ and blue neighbours $B$ with $|R|+|B|=|W|-1\ge
m+n-1$, so $|R|\ge m$ or $|B|\ge n$. If $|R|\ge m$, apply $m\to(s,t{+}1)$ to $R$: a
blue $(t{+}1)$-clique finishes; a red $s$-clique with $v$ gives a red
$(s{+}1)$-clique. The other case is symmetric.
\end{proof}

\begin{theorem}[Binomial bound, \texttt{arrows\_recursion}]\label{thm:binom}
For all $s,t$, $\binom{s+t}{s}\to(s{+}1,t{+}1)$, i.e.
$R(s{+}1,t{+}1)\le\binom{s+t}{s}$.
\end{theorem}
\begin{proof}[Proof sketch]
Double induction on $(s,t)$, base cases from single-vertex cliques, inductive step
from Lemma~\ref{lem:step}; thresholds add by Pascal's rule.
\end{proof}

In inequality form, $R(s,t)\le R(s-1,t)+R(s,t-1)$
(\texttt{arrows\_recursion\_general}).

\begin{theorem}[Off-diagonal base, \texttt{ramseyNumber\_two\_succ}]
$R(2,t+1)=t+1$.
\end{theorem}
\begin{proof}[Proof sketch]
Upper bound $R(2,t)\le t$: a colouring of $K_t$ has a red edge or is entirely
blue. Lower bound: the all-blue colouring of $K_t$ has no red edge and no blue
$K_{t+1}$. Apply Theorem~\ref{thm:sandwich}.
\end{proof}

\section{Colour symmetry}

\begin{lemma}[Colour swap, \texttt{arrows\_symm}]\label{lem:symm}
$n\to(s,t)\iff n\to(t,s)$, hence $R(s,t)=R(t,s)$.
\end{lemma}
\begin{proof}
Apply $n\to(s,t)$ to $G^{\cc}$: a red $s$-clique of $G^{\cc}$ is a blue $s$-clique
of $G$, and a blue $t$-clique of $G^{\cc\cc}=G$ is a red $t$-clique of $G$.
\end{proof}

\section{The exact small values}

\begin{theorem}[\texttt{ramseyNumber\_three\_three}]
$R(3,3)=6$.
\end{theorem}
\begin{proof}[Proof sketch]
Upper bound $6\to(3,3)$ is the $s=t=2$ instance of Theorem~\ref{thm:binom}, since
$\binom{4}{2}=6$. Lower bound: the pentagon $C_5$ on $\mathbb{Z}/5$ (neighbours
red) has no red triangle and its complement no blue triangle. Apply
Theorem~\ref{thm:sandwich}.
\end{proof}

\begin{lemma}[Handshake parity, \texttt{red\_nbrs\_sum\_even}]\label{lem:hand}
For any colouring $G$ and finite $W$, the total red-degree
$\sum_{v\in W}|\{w\in W:w\ne v,\ v\sim w\}|$ is even.
\end{lemma}

\begin{theorem}[\texttt{ramseyNumber\_three\_four}]
$R(3,4)=9$.
\end{theorem}
\begin{proof}[Proof sketch]
Upper bound $9\to(3,4)$: if a colouring of $K_9$ has no red triangle and no blue
$K_4$, local obstructions force every vertex to have red degree exactly $3$, so the
total red-degree is $9\cdot 3=27$ --- odd, contradicting Lemma~\ref{lem:hand}.
Lower bound: the M\"obius ladder $C_8(1,4)$ on $\mathbb{Z}/8$ (differences
$\{1,4\}$) is triangle-free with $K_4$-free complement. Apply
Theorem~\ref{thm:sandwich}.
\end{proof}

\begin{theorem}[\texttt{ramseyNumber\_four\_four}]
$R(4,4)=18$.
\end{theorem}
\begin{proof}[Proof sketch]
Upper bound $18\to(4,4)$: from $R(3,4)=9$ and colour symmetry $R(4,3)=9$, one step
(Lemma~\ref{lem:step}) gives $9+9=18\to(4,4)$. Lower bound: the Paley graph on
$\mathbb{Z}/17$ with $\QR_{17}=\{1,2,4,8,9,13,15,16\}$ (since $17\equiv1\pmod4$ the
residue set is symmetric and the graph self-complementary) has neither a red nor a
blue $K_4$. Apply Theorem~\ref{thm:sandwich}.
\end{proof}

\section{The diagonal: exponential bounds}

\begin{lemma}[Central binomial estimate, \texttt{central\_choose\_le\_four\_pow}]
$\binom{2k}{k}\le 4^k$.
\end{lemma}
\begin{proof}[Proof sketch]
One term of the row-sum $\sum_{i=0}^{2k}\binom{2k}{i}=2^{2k}=4^k$.
\end{proof}

\begin{theorem}[Exponential upper bound, \texttt{arrows\_diagonal\_pow}]
\label{thm:diag}
$4^k\to(k{+}1,k{+}1)$, i.e. $R(k{+}1,k{+}1)\le 4^k$.
\end{theorem}

We encode a colouring of $K_n$ by its red edge set $R$, where
$|E(K_n)|=\binom{n}{2}$; for a $k$-set $T$, $E(T)$ denotes its $\binom{k}{2}$
internal edges. Interval counting gives
$|\{R:E(T)\subseteq R\}|=|\{R:E(T)\cap R=\varnothing\}|=2^{\binom{n}{2}-\binom{k}{2}}$.

\begin{lemma}[Union bound, \texttt{exists\_good\_coloring}]
If $k\le n$ and $2\binom{n}{k}<2^{\binom{k}{2}}$, there is a red edge set $R$ with
no all-red and no all-blue $k$-set.
\end{lemma}

\begin{theorem}[Erd\H{o}s lower bound, \texttt{not\_arrows\_of\_counting}]
If $k\le n$ and $2\binom{n}{k}<2^{\binom{k}{2}}$ then $R(k,k)>n$.
\end{theorem}

\begin{corollary}[\texttt{not\_arrows\_of\_pow}]
Using $\binom{n}{k}\le n^k$: if $k\le n$ and $2n^k<2^{\binom{k}{2}}$ then
$R(k,k)>n$. In particular $R(10,10)>16$, since
$2\cdot16^{10}=2^{41}<2^{45}=2^{\binom{10}{2}}$.
\end{corollary}

\begin{theorem}[Even-diagonal sandwich, \texttt{ramsey\_even\_sandwich}]
For every $m\ge 4$,
\[
2^{\,m-1} \;<\; R(2m,2m) \;\le\; 4^{\,2m-1}.
\]
\end{theorem}
\begin{proof}[Proof sketch]
Lower: Corollary with $k=2m$, $n=2^{m-1}$; the side condition $2m\le2^{m-1}$ holds
from $m=4$, and the exponent inequality reduces to $1<m$. Upper: the
colour-diagonal of Theorem~\ref{thm:diag} at $k:=2m-1$. The interval is
non-degenerate for $m\ge 4$.
\end{proof}

\section{Algorithms}
\begin{enumerate}[leftmargin=*]
\item \textbf{Exhaustive arrow verifier:} enumerate all $2^{\binom{n}{2}}$
colourings of $K_n$ and check each for a red $K_s$ or blue $K_t$; correct but
exponential, feasible for tiny $n$.
\item \textbf{Erd\H{o}s--Szekeres dynamic program:} fill $R[s][t]=R[s-1][t]+
R[s][t-1]$ with $R[1][t]=R[s][1]=1$, returning binomial upper bounds in $O(st)$.
\item \textbf{Probabilistic threshold finder:} the largest $n$ with
$2\binom{n}{k}<2^{\binom{k}{2}}$ certifies $R(k,k)>n$.
\end{enumerate}

\section{Applications and discussion}
Ramsey-type arguments yield arithmetic-progression theorems in number theory, the
Erd\H{o}s--Szekeres convex-polygon theorem in geometry, and lower bounds in
theoretical computer science; the probabilistic method pervades randomized
algorithms and coding theory. The framework highlights the separation between
generic asymptotics (the exponential bound gives $R(3,3)\le16$, $R(4,4)\le64$) and
exact values ($6$, $18$), the latter recovered only by parity and algebra. Even
$R(5,5)$ is unknown ($43\le R(5,5)\le48$).

\section{Future directions}
\begin{enumerate}[leftmargin=*]
\item Off-diagonal closed form $R(3,t)\le(t^2+t+2)/2$ by telescoping the recursion
with $R(2,t)=t$.
\item Strict diagonal monotonicity $R(s,s)<R(s+1,s+1)$.
\item Super-polynomial growth of $R(k,k)$ from the exponential lower bound.
\item Sub-multiplicativity $R(s+t,s+t)\le R(2s,2s)\cdot R(2t,2t)$.
\item Tightness of the binomial bound iff $\min(s,t)\le 2$.
\end{enumerate}

\section{Conclusion}
We gave a unified development of two-colour Ramsey theory centred on the Ramsey
number as a computable function: the order-theoretic API, the Erd\H{o}s--Szekeres
recursion and binomial bound, colour symmetry, the exact values $R(3,3)=6$,
$R(3,4)=9$, $R(4,4)=18$, $R(2,t+1)=t+1$, and the sandwich
$2^{m-1}<R(2m,2m)\le4^{2m-1}$. The three exact values display three distinct
extremal mechanisms, illustrating that exactness is won case by case even as the
asymptotic framework is uniform.

