function ErdosSzekeresTable(max_s, max_t):
    R <- empty table
    for s from 1 to max_s:
        for t from 1 to max_t:
            if s == 1 or t == 1:
                R[s,t] <- 1
            else:
                R[s,t] <- R[s-1,t] + R[s,t-1]
    return R

